_nativeFacingCell(pid) {
      if (!this.alive[pid] || this.trapped[pid] > 0) return -1;
      const mv = this.lastMoveDir[pid];
      if (!(mv >= 0 && mv < MOVE_IDLE)) return -1;
      const [dy, dx] = DIRS[mv], y = this.pos[2 * pid], x = this.pos[2 * pid + 1];
      const row = Math.floor(y), col = Math.floor(x);
      if (this._nativeStaticBlocked(row, col)) return -1;
      for (let n = 1; n <= NATIVE_FACE_RANGE_CELLS; n++) {
        const r = row + dy * n, c = col + dx * n;
        if (r < 0 || r >= H || c < 0 || c >= W) break;
        const distance = (r + .5 - y) * dy + (c + .5 - x) * dx;
        if (distance > NATIVE_FACE_RANGE_CELLS + 1e-9) break;
        const cell = r * W + c;
        if (this.wall[cell] || this.brick[cell] || this.pushable[cell] || this.cover[cell]) break;
        if (this.fuse[cell] > 0) return cell;
      }
      return -1;
    }

